values.command:
$request = @'
{
  "schema_version": "1.0",
  "task_type": "summarize_table",
  "input_file": "D:\\bitexcel\\SheetPilot\\tests\\agent_contract\\data\\04_hard_multidimension.xlsx",
  "output_file": "<AUTO-RESULT-DIR>\\regional_category_summary.xlsx",
  "user_request": "使用交易流水，只统计审核状态为通过且未取消的记录。按区域、产品类别分组，输出净销售收入、交易数量（过滤后行数）、客户编号非空数量和平均交易金额，按净销售收入降序写入新工作表区域品类经营汇总。",
  "source": {
    "sheet": "交易流水",
    "header_row": 1
  },
  "filters": [
    {"id": "approved", "field": "审核状态", "operator": "eq", "value": "通过"},
    {"id": "not_canceled", "field": "是否取消", "operator": "eq", "value": "否"}
  ],
  "dimensions": [
    {"id": "region", "field": "区域", "output_name": "区域"},
    {"id": "category", "field": "产品类别", "output_name": "产品类别"}
  ],
  "metrics": [
    {"id": "net_sales", "function": "sum", "field": "净销售额", "output_name": "净销售收入"},
    {"id": "txn_count", "function": "count", "mode": "rows", "output_name": "交易数量"},
    {"id": "customer_count", "function": "count", "mode": "non_empty", "field": "客户编号", "output_name": "客户编号非空数量"},
    {"id": "avg_amount", "function": "average", "field": "净销售额", "output_name": "平均交易金额"}
  ],
  "output": {
    "sheet": "区域品类经营汇总",
    "anchor": "A1",
    "sort": [{"by": "net_sales", "direction": "desc"}]
  },
  "acceptance": {
    "required_filters": ["approved", "not_canceled"],
    "required_dimensions": ["region", "category"],
    "required_metrics": ["net_sales", "txn_count", "customer_count", "avg_amount"],
    "required_sort": [{"by": "net_sales", "direction": "desc"}]
  }
}
'@

$request | Out-File -FilePath "D:\bitexcel\SheetPilot\tests\agent_contract\results\task_request.json" -Encoding utf8
Write-Output "OK"
